// FoundryUpdateMutation supplies the typed update-draft adapter for framework integrations such as pivot updates. Omitted fields stay unchanged; no mutators or database calls run here.
func (d RecordDraft) FoundryUpdateMutation() (foundryquery.Mutation[Record], error) {
	return d.foundryMutation(false)
}

// FoundryCreateMutation supplies the typed draft adapter for framework integrations. Defaults fill omitted fields before UUID preparation; no mutators or database calls run here.
func (d RecordDraft) FoundryCreateMutation(defaults foundryquery.Mutation[Record]) (foundryquery.Mutation[Record], error) {
	values, err := foundryquery.ReadCreateDefaults((Record{}).FoundryQuery(), defaults)
	if err != nil {
		return foundryquery.Mutation[Record]{}, err
	}
	if !d.fieldID.IsSet() {
		v, err := foundryquery.MutationValue[Record, model.ID[Record]](values, "profile_records", "id")
		if err != nil {
			return foundryquery.Mutation[Record]{}, err
		}
		d.fieldID = v
	}
	if !d.fieldName.IsSet() {
		v, err := foundryquery.MutationValue[Record, string](values, "profile_records", "name")
		if err != nil {
			return foundryquery.Mutation[Record]{}, err
		}
		d.fieldName = v
	}
	if !d.fieldActive.IsSet() {
		v, err := foundryquery.MutationValue[Record, bool](values, "profile_records", "active")
		if err != nil {
			return foundryquery.Mutation[Record]{}, err
		}
		d.fieldActive = v
	}
	if !d.fieldScore.IsSet() {
		v, err := foundryquery.MutationValue[Record, int64](values, "profile_records", "score")
		if err != nil {
			return foundryquery.Mutation[Record]{}, err
		}
		d.fieldScore = v
	}
	if !d.fieldPayload.IsSet() {
		v, err := foundryquery.MutationValue[Record, []byte](values, "profile_records", "payload")
		if err != nil {
			return foundryquery.Mutation[Record]{}, err
		}
		d.fieldPayload = v
	}
	if !d.fieldNote.IsSet() {
		v, err := foundryquery.MutationValue[Record, foundryvalue.Nullable[string]](values, "profile_records", "note")
		if err != nil {
			return foundryquery.Mutation[Record]{}, err
		}
		d.fieldNote = v
	}
	return d.foundryMutation(true)
}
func (d RecordDraft) foundryMutation(create bool) (foundryquery.Mutation[Record], error) {
	if create && !d.fieldID.IsSet() {
		id, err := model.NewID[Record]()
		if err != nil {
			return foundryquery.Mutation[Record]{}, err
		}
		d = d.SetID(id)
	}
	var assignments []foundryquery.Assignment[Record]
	if v, set := d.fieldID.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Record]("profile_records", "id", codec.ID[Record](), v))
	}
	if v, set := d.fieldName.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Record]("profile_records", "name", codec.String[string](), v))
	}
	if v, set := d.fieldActive.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Record]("profile_records", "active", codec.Bool[bool](), v))
	}
	if v, set := d.fieldScore.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Record]("profile_records", "score", codec.Signed[int64](), v))
	}
	if v, set := d.fieldPayload.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Record]("profile_records", "payload", codec.Bytes[[]byte](), v))
	}
	if v, set := d.fieldNote.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Record]("profile_records", "note", codec.Nullable(codec.String[string]()), v))
	}
	return foundryquery.Change(assignments...), nil
}

